"""Transient exact-package probes; native commands use disposable profiles only."""
import sys,json,subprocess,hashlib,os
from pathlib import Path
from marketplace_run import WORK,command,OUT
sys.path.insert(0,str(WORK/'iar-demo-tools'))
from run_demo import child_env
OLD=Path(json.loads((WORK/'iar-demo-tools/prepared-demo.json').read_text())['demo'])
MARKET=WORK/'marketplace-021-distribution'
HOSTS={'codex':r'C:\Users\mathi\AppData\Local\OpenAI\Codex\bin\faa963e871dd422c\codex.exe','claude':r'C:\Users\mathi\.local\bin\claude.exe'}
def run(base,host,label,args):
    env=child_env(base,host)
    for k in ('CODEX_HOME','CLAUDE_CONFIG_DIR','APPDATA','LOCALAPPDATA','TEMP'):Path(env[k]).mkdir(exist_ok=True,parents=True)
    r=command(label,[HOSTS[host],*args],cwd=WORK,env=env,timeout=180)
    if r.returncode:raise RuntimeError(label+' failed')
    return r.stdout
def compare(plugin,host):
    expected=MARKET/'packages'/host/'verity-plane'
    hashes={p.relative_to(expected).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in expected.rglob('*') if p.is_file()}
    actual={path:hashlib.sha256((plugin/path).read_bytes()).hexdigest() for path in hashes}
    assert hashes==actual
    return {'path':str(plugin),'compared_files':len(hashes),'content_sha256':hashlib.sha256(json.dumps(hashes,sort_keys=True,separators=(',',':')).encode()).hexdigest(),'files':hashes}
def selected(base,host,label):
    data=json.loads(run(base,host,label,['plugin','list',*(['--marketplace','se-harness'] if host=='codex' else []),'--json']))
    if host=='codex':data=data['installed']
    key='pluginId' if host=='codex' else 'id'
    return next(row for row in data if row[key]=='verity-plane@se-harness')
mode=sys.argv[1]
if mode=='old-state':
    for host in HOSTS:
        print(json.dumps({'host':host,'plugin':selected(OLD,host,'old-'+host+'-plugins')}))
        run(OLD,host,'old-'+host+'-marketplaces',['plugin','marketplace','list','--json'])
elif mode=='replace-old':
    for host in HOSTS:
        before=json.loads((OUT/('old-'+host+'-plugins.stdout')).read_text())
        rows=before['installed'] if host=='codex' else before
        key='pluginId' if host=='codex' else 'id'
        old=next(x for x in rows if x[key]=='verity-plane@se-harness')
        assert old['version']=='0.2.0',old
        run(OLD,host,'replace-'+host+'-remove-source',['plugin','marketplace','remove','se-harness'])
        run(OLD,host,'replace-'+host+'-add-source',['plugin','marketplace','add',str(MARKET),*(['--json'] if host=='codex' else [])])
        result=run(OLD,host,'replace-'+host+'-install',['plugin','add' if host=='codex' else 'install','verity-plane@se-harness','--json'])
        row=selected(OLD,host,'replace-'+host+'-plugins')
        assert row['version']=='0.2.1',row
        plugin=Path(json.loads(result)['installedPath']) if host=='codex' else Path(row['installPath'])
        summary={'before':old,'after':row,**compare(plugin,host),'profile_base':str(OLD)}
        (OUT/(host+'-replacement.json')).write_text(json.dumps(summary,indent=2)+'\n')
        print(json.dumps({'host':host,'version':row['version'],'compared_files':summary['compared_files']}))
